extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return
	var player := find_by_name(main, "Player") as CharacterBody2D
	if not check("player", player != null, "Il nodo Player deve essere presente"):
		return
	var tree := find_by_name(player, "AnimationTree") as AnimationTree
	if not check("tree", tree != null, "Il nodo AnimationTree deve essere presente"):
		return
	var playback: AnimationNodeStateMachinePlayback = tree.get("parameters/playback")
	if not check("playback", playback != null, "L'AnimationTree deve avere una root StateMachine attiva"):
		return
	await wait_physics_frames(5)
	var blend_val = tree.get("parameters/move_blend/blend_position")
	check("blend_idle", blend_val != null and absf(float(blend_val)) < 0.05, "Da fermo blend_position deve essere vicino a 0.0")
	check("state_blend", playback.get_current_node() == &"move_blend", "Lo stato attivo della macchina a stati deve essere 'move_blend'")
	await hold_action("move_right", 20)
	blend_val = tree.get("parameters/move_blend/blend_position")
	check("blend_run", blend_val != null and float(blend_val) > 0.8, "Alla massima velocità blend_position deve salire verso 1.0 (misurato: %s)" % str(blend_val))
	await wait_physics_frames(10)
	await tap_action("attack")
	await wait_physics_frames(3)
	check("state_attack", playback.get_current_node() == &"attack", "L'attacco deve continuare ad attivare lo stato 'attack'")

